    12	static float measurement(size_t i,int seed) {
    13	    if(i%65536==0)return 0.0f;
    14	    if(i%65536==1)return 1.0f;
    15	    uint32_t a=uint32_t(i*1664525u+uint32_t(seed)*1013904223u);
    16	    a^=a>>16;a*=2246822519u;a^=a>>13;a*=3266489917u;a^=a>>16;
    17	    const uint32_t code=uint32_t(256u+(a%65280u));
    18	    const float fraction=float((a>>16)&0xffffu)/65536.0f;
    19	    const float raw=(float(code)+fraction)/65535.0f;
    20	    return std::min(1.0f,raw);
    21	}
    22	static double calibration(double x) {
    23	    return -std::log1p(-0.97*x)/0.85+0.20*std::log1p(0.30*x)+0.03+0.02*x*x;
    24	}
