    26	static int run_audit(int w,int h,int seed) {
    27	    const size_t n=size_t(w)*size_t(h);
    28	    double bins[32][3]={};
    29	    size_t ids[8]={0,size_t(size_t(n>1?1:0)),n/7,n/3,n/2,(2*n)/3,size_t(size_t(n>1?n-2:0)),n-1};
    30	    for(size_t i=0;i<n;++i){double q=calibration(double(measurement(i,seed)));int b=int(i%32);bins[b][0]+=q;bins[b][1]+=q*q;bins[b][2]+=q>=3.8?1.0:0.0;}
    31	    double samples[8];for(int j=0;j<8;++j)samples[j]=calibration(double(measurement(ids[j],seed)));
    32	    const size_t persistentBytes=kCurveSize*sizeof(float);
    33	    const size_t bytes=persistentBytes+sizeof(bins)+sizeof(samples)+sizeof(ids);
    34	    std::cout<<std::setprecision(13)<<"{\"storage_bytes\":"<<bytes<<",\"persistent_storage_bytes\":"<<persistentBytes<<",\"checksums\":[";
    35	    for(int b=0;b<32;++b){if(b)std::cout<<',';std::cout<<'['<<bins[b][0]<<','<<bins[b][1]<<','<<bins[b][2]<<']';}
    36	    std::cout<<"],\"samples\":[";for(int j=0;j<8;++j){if(j)std::cout<<',';std::cout<<samples[j];}std::cout<<"]}\n";
    37	    return 0;
    38	}
