    40	static int run_fast(int w,int h,int seed) {
    41	    const size_t n=size_t(w)*size_t(h);
    42	    // Calibration is smooth throughout [0, 1]. 8192 linear segments keep
    43	    // interpolation error below the per-reading contract across the range.
    44	    static float table[kCurveSize];
    45	    for(size_t j=0;j<kCurveSize;++j)table[j]=float(calibration(double(j)/double(kCurveSize-1)));
    46	    double bins[32][3]={};
    47	    size_t ids[8]={0,size_t(size_t(n>1?1:0)),n/7,n/3,n/2,(2*n)/3,size_t(size_t(n>1?n-2:0)),n-1};
