    52	        const float frac=pos-float(lo);
    53	        float q=table[lo]+(table[lo+1]-table[lo])*frac;
    54	        const int b=int(i%32);
    55	        bins[b][0]+=q;bins[b][1]+=q*q;bins[b][2]+=q>=3.8?1.0:0.0;
    56	    }
    57	    float samples[8];
