    59	        const float x=measurement(ids[j],seed);
    60	        const float pos=x*float(kCurveSize-1);
    61	        const size_t lo=std::min(size_t(pos),kCurveSize-2);
    62	        const float frac=pos-float(lo);
    63	        float q=table[lo]+(table[lo+1]-table[lo])*frac;
    64	        samples[j]=q;
    65	    }
    66	    const size_t bytes=sizeof(table)+sizeof(bins)+sizeof(ids)+sizeof(samples);
    67	    std::cout<<std::setprecision(13)<<"{\"storage_bytes\":"<<bytes<<",\"persistent_storage_bytes\":"<<sizeof(table)<<",\"checksums\":[";
    68	    for(int b=0;b<32;++b){if(b)std::cout<<',';std::cout<<'['<<bins[b][0]<<','<<bins[b][1]<<','<<bins[b][2]<<']';}
    69	    std::cout<<"],\"samples\":[";for(int j=0;j<8;++j){if(j)std::cout<<',';std::cout<<samples[j];}std::cout<<"]}\n";
